WITH base AS (SELECT id, supplier_name, rating, CONCAT(supplier_name, ' - ', city) AS supplier_name_city, CASE WHEN rating >= 4.0 THEN 'High' WHEN rating >= 1.7 THEN 'Medium' ELSE 'Low' END AS rating_tier FROM suppliers WHERE rating BETWEEN 3.0 AND 3.3), with_windows AS (SELECT id, rating, rating_tier, NTILE(3) OVER (ORDER BY rating, id) AS rating_bucket, SUM(rating) OVER (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_rating FROM base), kept AS (SELECT s.* FROM with_windows s WHERE EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND c.category = 'Books')), scored AS (SELECT id, rating_tier, MIN(cumulative_rating) OVER w_part AS running_min_cumulative_rating, MAX(cumulative_rating) OVER w_part AS running_max_cumulative_rating, SUM(cumulative_rating) OVER w_part AS running_sum_cumulative_rating FROM kept WHERE rating < 1.9 WINDOW w_part AS (ORDER BY rating, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), eligible AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM products x WHERE x.supplier_id = s.id AND x.price > 1100)) SELECT CASE WHEN running_min_cumulative_rating >= 18.6 THEN 'HIGH' ELSE 'LOW' END AS running_min_cumulative_rating_tier, ROUND(AVG(running_min_cumulative_rating), 2) AS avg_running_min_cumulative_rating, COUNT(DISTINCT id) AS distinct_ids, MAX(running_min_cumulative_rating) AS max_running_min_cumulative_rating, COUNT(DISTINCT id) AS distinct_ids_2, ROUND(AVG(running_sum_cumulative_rating), 2) AS avg_running_sum_cumulative_rating, GROUPING_ID() AS gid FROM eligible GROUP BY CUBE (CASE WHEN running_min_cumulative_rating >= 18.6 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(DISTINCT id) < 1000 ORDER BY max_running_min_cumulative_rating NULLS FIRST
